package com.keyforge.nativeload;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class NativeWorkgroupMembershipRepositoryTest {@Test void relationshipIdIsDeterministicForEndpointPair(){NativeWorkgroupMembershipRecord r=new NativeWorkgroupMembershipRecord();r.workgroupId="11111111111111111111111111111111";r.identityId="22222222222222222222222222222222";assertEquals(NativeWorkgroupMembershipRepository.edgeId(r),NativeWorkgroupMembershipRepository.edgeId(r));} @Test void hashChangesWithBusinessContentButNotLineage(){NativeWorkgroupMembershipRecord a=new NativeWorkgroupMembershipRecord();a.workgroupId="11111111111111111111111111111111";a.identityId="22222222222222222222222222222222";a.identityName="A";NativeWorkgroupMembershipRecord b=new NativeWorkgroupMembershipRecord();b.workgroupId=a.workgroupId;b.identityId=a.identityId;b.identityName="A";b.runId="another-run";assertEquals(NativeWorkgroupMembershipRepository.hash(a),NativeWorkgroupMembershipRepository.hash(b));b.identityName="B";assertNotEquals(NativeWorkgroupMembershipRepository.hash(a),NativeWorkgroupMembershipRepository.hash(b));}}
